int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct buffer_head *bh = NULL;
    struct ext4_ext_path *path = NULL;
    ext4_lblk_t goal;
    int error = 0;
    int depth;

    depth = ext4_ext_depth(inode);
    goal = (ext4_lblk_t)EXT4_I(inode)->i_disksize >> (depth * EXT4_EXTENT_T_SIZE_BITS);

    bh = ext4_get_block(inode, goal, NULL, flags);
    if (IS_ERR(bh)) {
        error = PTR_ERR(bh);
        goto out;
    }

    lock_buffer(bh);
    if (!buffer_journal_head(bh)) {
        error = ext4_journal_get_write_access(handle, bh);
        if (error)
            goto out_unlock;
    }

    path = ext4_ext_binsearch(inode, goal);
    if (!path) {
        error = -EINVAL;
        goto out_unlock;
    }

    error = ext4_ext_move_inode_table(inode, bh, path);
    if (error)
        goto out_unlock;

    ext4_extent_header_init(inode, bh);
    EXT4_I(inode)->i_ext_max = goal + 1;
    EXT4_I(inode)->i_ext_generation++;

    mark_inode_dirty(inode);

    unlock_buffer(bh);
    brelse(bh);

out:
    kfree(path);
    return error;

out_unlock:
    unlock_buffer(bh);
    brelse(bh);
    goto out;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct buffer_head *bh = NULL;
    struct ext4_ext_path *path = NULL;
    ext4_lblk_t goal;
    int ret = 0;

    goal = ext4_ext_find_goal(inode, 0);

    bh = ext4_get_block(inode, goal, flags);
    if (IS_ERR_OR_NULL(bh)) {
        ret = PTR_ERR(bh);
        goto out;
    }

    lock_buffer(bh);
    if (!buffer_journal_head(bh)) {
        ret = -EINVAL;
        goto unlock;
    }

    path = ext4_ext_build_path(inode, bh, flags);
    if (IS_ERR(path)) {
        ret = PTR_ERR(path);
        goto unlock;
    }

    ret = ext4_ext_replay(inode, path, bh, flags);
    if (ret)
        goto out;

    ext4_ext_init_header(inode, bh, flags);
    ext4_inode_set_dirty(handle, inode);
    unlock:
    unlock_buffer(bh);
    brelse(bh);
out:
    kfree(path);
    return ret;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct buffer_head *bh = NULL;
    struct ext4_ext_path *path = NULL;
    struct ext4_extent_header *eh;
    ext4_lblk_t goal;
    int err = 0;

    goal = ext4_ext_get_actual_len(&EXT4_I(inode)->i_ext) + 1;

    path = kmalloc(sizeof(struct ext4_ext_path) * (EXT4_MAX_EXTENT_DEPTH + 1), GFP_NOFS);
    if (!path) {
        err = -ENOMEM;
        goto out;
    }

    err = ext4_ext_walk(inode, &path, &bh, NULL);
    if (err)
        goto out;

    if (!bh) {
        err = -ENOSPC;
        goto out;
    }

    lock_buffer(bh);

    eh = (struct ext4_extent_header *)bh->b_data;
    ext4_extent_header_init(eh);

    err = ext4_handle_dirty_metadata(handle, NULL, bh);
    if (err)
        goto unlock;

    ext4_ext_move(path, bh, goal);

    EXT4_I(inode)->i_ext.lblk = goal;
    EXT4_I(inode)->i_ext.pblk = bh->b_blocknr;
    EXT4_I(inode)->i_ext.len = 1;

    mark_inode_dirty(inode);

unlock:
    unlock_buffer(bh);
    brelse(bh);
out:
    kfree(path);
    return err;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    int err = 0;
    struct buffer_head *bh = NULL;
    struct ext4_extent *ex;
    struct ext4_extent_header *eh;
    ext4_lblk_t goal;

    goal = ext4_ext_get_actual_len(inode->i_sb, inode, 0, flags);

    bh = ext4_find_goal_block(inode, goal, flags);
    if (!bh) {
        err = -ENOSPC;
        goto out;
    }

    lock_buffer(bh);
    if (ext4_journal_get_write_access(handle, bh)) {
        err = -EIO;
        goto unlock_out;
    }

    ex = (struct ext4_extent *)bh->b_data;
    eh = ext4_ext_get_header(inode);
    memcpy(ex, eh, sizeof(*eh) + le16_to_cpu(eh->eh_entries) * sizeof(*ex));

    ext4_ext_init_header(inode, bh);
    ext4_ext_mark_inode_dirty(inode, handle);
    inode->i_mtime = inode->i_ctime = current_time(inode);
    mark_inode_dirty(inode);

unlock_out:
    unlock_buffer(bh);
    brelse(bh);
out:
    return err;
}

int ext4_ext_grow(handle_t *handle, struct inode *inode, unsigned int flags) {
    struct buffer_head *bh = NULL;
    struct ext4_extent *ex;
    struct ext4_extent_header *eh;
    struct ext4_inode_info *ei = EXT4_I(inode);
    int ret = 0;

    // Determine the goal block for the new extent based on current depth
    unsigned long goal_block = ei->i_disksize >> inode->i_sb->s_blocksize_bits;

    // Allocate a new block
    bh = ext4_alloc_block(handle, goal_block, flags);
    if (IS_ERR(bh)) {
        ret = PTR_ERR(bh);
        goto out;
    }

    // Lock the buffer and prepare it for journal access
    lock_buffer(bh);
    ret = ext4_journal_get_write_access(handle, bh);
    if (ret) {
        unlock_buffer(bh);
        goto out;
    }

    // Move the existing extent data into the new block
    ex = (struct ext4_extent *)bh->b_data;
    eh = &ei->i_ext.ext_header;

    // Initialize the new extent header
    eh->eh_depth = eh->eh_depth + 1;
    eh->eh_entries = 0;

    // Copy existing extent data into new block
    memcpy(ex, &ei->i_ext.ext_tree[0], sizeof(struct ext4_extent));

    // Update the inode's extent information
    ei->i_ext.largest = 0;
    ei->i_ext.count++;

    // Mark the inode as dirty
    mark_inode_dirty(inode);

    // Release the buffer
    unlock_buffer(bh);
    brelse(bh);

out:
    return ret;
}
